import type { paths } from "./paths.gen";

// Typed client over the Huma API. Two auth paths, both accepted by the server: a
// human signs in with a password and gets an httpOnly session cookie (sent
// automatically because every request includes credentials), and a service or
// operator can instead paste a bearer token, which is stored and attached as an
// Authorization header. The base is origin-absolute so it resolves in every fetch
// implementation (the browser, and undici in tests). Types come from orval's
// api.gen.ts, indexed by route in paths.gen.ts (both regenerated by `make gen`),
// so the client cannot drift (ADR-1619).
const TOKEN_KEY = "og-token";

export function getToken(): string {
  return localStorage.getItem(TOKEN_KEY) ?? "";
}
export function setToken(token: string): void {
  localStorage.setItem(TOKEN_KEY, token);
}
export function clearToken(): void {
  localStorage.removeItem(TOKEN_KEY);
}

const origin = typeof globalThis.location !== "undefined" ? globalThis.location.origin : "";
const BASE_URL = `${origin}/api/v1`;

// onUnauthorized fires when a request to a protected route is rejected with 401,
// which means a session that WAS valid has ended (expired, revoked by a password
// reset, or the account locked out). The app registers a handler (in index.tsx)
// that drops the cached principal so the AuthGuard bounces to /login immediately,
// rather than waiting for /auth/me to refetch on its own. Nil until registered.
let onUnauthorized: (() => void) | null = null;
export function setUnauthorizedHandler(fn: () => void): void {
  onUnauthorized = fn;
}

// The auth endpoints handle their own 401s (an anonymous /auth/me, a bad-password
// /auth/login, the public /auth/status), so a 401 from them is not a "bumped
// session" and must not trigger the global bounce.
function isAuthEndpoint(url: string): boolean {
  return /\/auth\/(me|login|status)$/.test(url.split("?")[0]);
}

// send is the one transport: it resolves a route-relative url under the api base,
// includes credentials (the console is same-origin, served by the binary with vite
// proxying /api in dev, so the session cookie rides anyway; include is for
// robustness), attaches a stored bearer token on top of the cookie (the server
// accepts either), and on a 401 from any other route signals that the session has
// ended so the guard can redirect. It defers to the current global fetch on every
// call so tests can stub it.
async function send(url: string, init: RequestInit): Promise<{ request: Request; response: Response }> {
  const request = new Request(`${BASE_URL}${url}`, { redirect: "follow", ...init, credentials: "include" });
  const token = getToken();
  if (token) request.headers.set("Authorization", `Bearer ${token}`);
  const response = await globalThis.fetch(request);
  if (response.status === 401 && !isAuthEndpoint(request.url)) onUnauthorized?.();
  return { request, response };
}

// ogFetch is the mutator orval's generated operations call (orval.config.mjs), so
// each of them goes through send and returns orval's { data, status, headers }.
export async function ogFetch<T>(url: string, init: RequestInit): Promise<T> {
  const { response } = await send(url, init);
  const text = [204, 205, 304].includes(response.status) ? "" : await response.text();
  const data = text ? JSON.parse(text) : {};
  return { data, status: response.status, headers: response.headers } as T;
}

// The path-keyed client the data layer calls: api.GET(route, { params, body })
// resolves to { data, error, response }, exactly one of data and error set by
// whether the response is ok, the shape openapi-fetch gave every call site.
type Method = "get" | "put" | "post" | "delete" | "patch";
type Routes<M extends Method> = { [R in keyof paths]: paths[R] extends Record<M, unknown> ? R : never }[keyof paths];
type Op<R extends keyof paths, M extends Method> = paths[R] extends Record<M, infer O extends Shape> ? O : never;

type Shape = { path: unknown; query: unknown; body: unknown; bodyRequired: boolean; data: unknown; error: unknown };
type PathParams<O extends Shape> = [O["path"]] extends [never] ? { path?: never } : { path: O["path"] };
type QueryParams<O extends Shape> = [O["query"]] extends [never] ? { query?: never } : { query?: O["query"] };
type Body<O extends Shape> = [O["body"]] extends [never]
  ? { body?: never }
  : O["bodyRequired"] extends true
    ? { body: O["body"] }
    : { body?: O["body"] };
type Init<O extends Shape> = { params?: PathParams<O> & QueryParams<O> } & Body<O> & Omit<RequestInit, "body" | "method">;
// The init is required when the route has a path param or a required body.
type InitArg<O extends Shape> = [O["path"]] extends [never]
  ? O["bodyRequired"] extends true
    ? [init: Init<O> & { body: O["body"] }]
    : [init?: Init<O>]
  : [init: Init<O> & { params: PathParams<O> & QueryParams<O> }];

export type ApiResult<O extends Shape> =
  | { data: O["data"]; error?: never; response: Response }
  | { data?: never; error: O["error"]; response: Response };

type Params = { path?: Record<string, string | number | boolean>; query?: Record<string, unknown> };

// routeUrl fills a route's {param}s, each encoded, and appends the set query params.
function routeUrl(route: string, params: Params): string {
  const path = route.replace(/\{([^{}]+)\}/g, (_, name: string) => encodeURIComponent(String(params.path?.[name])));
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(params.query ?? {})) {
    if (value !== undefined && value !== null) query.append(key, String(value));
  }
  const search = query.toString();
  return search ? `${path}?${search}` : path;
}

async function call(method: string, route: string, init: { params?: Params; body?: unknown } & RequestInit = {}) {
  const { params = {}, body, ...rest } = init;
  const headers = new Headers(rest.headers);
  if (body !== undefined && !headers.has("Content-Type")) headers.set("Content-Type", "application/json");
  const { request, response } = await send(routeUrl(route, params), {
    ...rest,
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const length = response.headers.get("Content-Length");
  const chunked = response.headers.get("Transfer-Encoding")?.includes("chunked");
  if (response.status === 204 || request.method === "HEAD" || (length === "0" && !chunked)) {
    return response.ok ? { data: undefined, response } : { error: undefined, response };
  }
  const text = await response.text();
  if (response.ok) return { data: text ? JSON.parse(text) : undefined, response };
  let error: unknown = text;
  try {
    error = JSON.parse(text);
  } catch {
    // Not JSON: the error is the body's text.
  }
  return { error, response };
}

function verb<M extends Method>(method: M) {
  return <R extends Routes<M>>(route: R, ...init: InitArg<Op<R, M>>): Promise<ApiResult<Op<R, M>>> =>
    call(method.toUpperCase(), route, init[0] as Parameters<typeof call>[2]) as Promise<ApiResult<Op<R, M>>>;
}

export const api = {
  GET: verb("get"),
  PUT: verb("put"),
  POST: verb("post"),
  DELETE: verb("delete"),
  PATCH: verb("patch"),
};
